use riscv_instruction_schema::Instruction;

const EMBEDDED_JSON: &str = include_str!("../../assets/riscv_instructions.json");

/// Load the catalog of RISC-V instructions embedded into the scanner binary
/// at compile time. The source of truth is `assets/riscv_instructions.json`
/// in the workspace root, regenerated by `riscv-instruction-parser`.
pub fn load_instructions() -> Result<Vec<Instruction>, serde_json::Error> {
    serde_json::from_str(EMBEDDED_JSON)
}
